import{_ as I,o as a,c as l,a2 as s}from"./chunks/framework.BauHmMU1.js";const e="data:image/svg+xml;base64,",h=JSON.parse('{"title":"第 9 章 常见问题与解决方案（FAQ）","description":"","frontmatter":{},"headers":[],"relativePath":"09-faq.md","filePath":"09-faq.md","lastUpdated":1792595797000}'),n={name:"09-faq.md"};function d(g,i,t,p,o,c){return a(),l("div",null,[...i[0]||(i[0]=[s(`<h1 id="第-9-章-常见问题与解决方案-faq" tabindex="-1">第 9 章 常见问题与解决方案（FAQ） <a class="header-anchor" href="#第-9-章-常见问题与解决方案-faq" aria-label="Permalink to &quot;第 9 章 常见问题与解决方案（FAQ）&quot;">​</a></h1><h2 id="q1-连接几分钟没消息就断开了-怎么办" tabindex="-1">Q1：连接几分钟没消息就断开了，怎么办？ <a class="header-anchor" href="#q1-连接几分钟没消息就断开了-怎么办" aria-label="Permalink to &quot;Q1：连接几分钟没消息就断开了，怎么办？&quot;">​</a></h2><p><strong>原因</strong>：中间链路（Nginx、云负载均衡、公司代理）会回收空闲 TCP 连接，典型空闲超时 60s。</p><p><strong>方案</strong>：</p><ol><li>应用内实现心跳（见第 6.1 节），心跳间隔务必<strong>小于</strong>中间件空闲超时（建议 ≤30s）。</li><li>Nginx 反向代理配置示例：</li></ol><div class="language-nginx vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> /ws </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://backend;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_http_version </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Upgrade $http_upgrade;      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 必须：传递 Upgrade 头</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Connection </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;upgrade&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 必须：传递 Connection 头</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_read_timeout </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3600s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;                    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 调大空闲超时（默认 60s）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><img src="`+e+'" alt="Nginx 反向代理 wss 长连接部署拓扑"></p><h2 id="q2-为什么收不到对方断开的通知-半开连接" tabindex="-1">Q2：为什么收不到对方断开的通知（半开连接）？ <a class="header-anchor" href="#q2-为什么收不到对方断开的通知-半开连接" aria-label="Permalink to &quot;Q2：为什么收不到对方断开的通知（半开连接）？&quot;">​</a></h2><p>TCP 设计上，对端断电/断网时本地不会有任何事件——发送缓冲区还有数据时才会在重传超时后报错。<strong>唯一可靠的检测手段就是应用自己定期发心跳</strong>。这是 WebSocket 开发最经典的问题。</p><h2 id="q3-消息发送失败-丢失怎么办" tabindex="-1">Q3：消息发送失败/丢失怎么办？ <a class="header-anchor" href="#q3-消息发送失败-丢失怎么办" aria-label="Permalink to &quot;Q3：消息发送失败/丢失怎么办？&quot;">​</a></h2><p>WebSocket 基于 TCP，<strong>单条消息内不丢、不乱序</strong>，但不保证：</p><ul><li>发送时连接恰好断开 → <code>send()</code> 静默失败或抛异常</li><li>重连期间的消息 → 完全丢失</li></ul><p><strong>方案</strong>：应用层 ACK 机制——每条消息带唯一 <code>clientId</code>，服务端收到后回执；客户端超时未收到回执则重发（服务端用 <code>clientId</code> 幂等去重）。</p><h2 id="q4-浏览器控制台报-websocket-connection-failed-怎么排查" tabindex="-1">Q4：浏览器控制台报 <code>WebSocket connection failed</code> 怎么排查？ <a class="header-anchor" href="#q4-浏览器控制台报-websocket-connection-failed-怎么排查" aria-label="Permalink to &quot;Q4：浏览器控制台报 `WebSocket connection failed` 怎么排查？&quot;">​</a></h2><p>按顺序检查：</p><ol><li>服务端是否启动、端口是否正确（<code>lsof -i :8080</code>）</li><li><code>ws://</code> 与 <code>wss://</code> 是否用错——<strong>HTTPS 页面只能连 <code>wss://</code></strong>（混合内容限制）</li><li>经过 Nginx/网关时，Upgrade 头是否正确透传（见 Q1 配置）</li><li>跨域问题：WebSocket 不受 CORS 限制，但服务端应校验 <code>Origin</code> 头防 CSWSH 攻击</li></ol><h2 id="q5-并发连接数上不去" tabindex="-1">Q5：并发连接数上不去？ <a class="header-anchor" href="#q5-并发连接数上不去" aria-label="Permalink to &quot;Q5：并发连接数上不去？&quot;">​</a></h2><ul><li>文件描述符限制：<code>ulimit -n</code> 调大（生产建议 65535+）</li><li>Node.js 单进程内存：每个连接约 10~20KB，10 万连接约 2GB</li><li>垂直扩展有限时，用 Redis Pub/Sub 做多进程/多机的消息广播总线</li></ul><h2 id="q6-json-太慢-太大" tabindex="-1">Q6：JSON 太慢/太大？ <a class="header-anchor" href="#q6-json-太慢-太大" aria-label="Permalink to &quot;Q6：JSON 太慢/太大？&quot;">​</a></h2><p>文本 JSON 适合大多数场景；真正遇到瓶颈时：</p><ul><li>二进制序列化：MessagePack / Protobuf（体积减 30~70%，CPU 减半）</li><li>高频小消息合并成批次发送（牺牲数 ms 延迟换吞吐）</li></ul><hr>',22)])])}const m=I(n,[["render",d]]);export{h as __pageData,m as default};
